use implicit_predicates::Sign;
use implicit_predicates_oracle::Dyadic;

/// The exact sign of the predicate at the points with the exact coordinates
/// `c`: its main form, evaluated with exact dyadic numbers in the order of the
/// definition.
pub fn exact_at(c: &[[Dyadic; 3]; 3]) -> Sign {
    let t0 = &c[0][0] - &c[1][0];
    let t1 = &c[0][1] - &c[1][1];
    let t2 = &c[0][2] - &c[1][2];
    let t3 = &c[2][0] - &c[1][0];
    let t4 = &c[2][1] - &c[1][1];
    let t5 = &c[2][2] - &c[1][2];
    let t6 = &t0 * &t3;
    let t7 = &t1 * &t4;
    let t8 = &t6 + &t7;
    let t9 = &t2 * &t5;
    let det = &t8 + &t9;
    match det.sign() {
        1 => Sign::Positive,
        -1 => Sign::Negative,
        _ => Sign::Zero,
    }
}

/// The exact sign of the predicate at the points `p`: [`exact_at`] on their
