/// Runs `decide` on every case of [`bound_edge_cases`] and checks that,
/// whenever it decides, its sign is the exact sign. Returns how many cases it
/// decided and how many it declined.
///
/// # Panics
///
/// Panics if `decide` gives a sign other than the exact sign.
pub fn check_bound_edge_cases(
    mut decide: impl FnMut(&[[f64; 3]; 3]) -> Option<Sign>,
) -> [usize; 2] {
    let mut counts = [0; 2];
    for p in bound_edge_cases() {
        match decide(&p) {
            Some(sign) => {
                assert_eq!(sign, exact(&p), "{p:?}");
                counts[0] += 1;
            }
            None => counts[1] += 1,
        }
    }
    counts
}

/// Runs `decide`, a stage that takes the approximations `p` and the uncertainty
/// `e` as `filter_axes` does, on every case of [`axes_edge_cases`], and checks
/// that, whenever it decides, its sign is the exact sign: with `e = 0`, at `p`;
/// otherwise, not zero and the exact sign at 20 of the `2^9` corners of the
/// boxes of an error of `e[k] / 2` for every point on each axis `k` around the
/// approximations: the corner with every coordinate at its lowest, the one with
/// every coordinate at its highest, and each corner one coordinate away from
/// either. The predicate need not be affine in each coordinate, so this does
/// not show that the sign holds in the whole boxes.
///
/// Then, for each pair with an uncertainty, whose terms of kappa exceed `2^10`
/// times its terms of epsilon, checks that `decide` declines the first input of
/// the pair with `2 e`, where the bound is near twice the exact value, and
/// decides the second with `e / 2`, where it is near half of it, with its exact
/// sign: a bound with a term of kappa much too small, or much too large, fails
/// here although no sign is wrong.
///
/// Returns how many cases it decided and how many it declined, with `e = 0` and
/// with an uncertainty.
///
/// # Panics
///
/// Panics if `decide` gives a sign that does not hold at a corner it checks,
/// decides a first input with `2 e`, or does not decide a second input with `e
/// / 2`.
pub fn check_axes_edge_cases(
    mut decide: impl FnMut(&[[f64; 3]; 3], [f64; 3]) -> Option<Sign>,
) -> [[usize; 2]; 2] {
    let mut counts = [[0; 2]; 2];
    let cases = axes_edge_cases();
    for (p, e) in &cases {
        let kind = usize::from(e.iter().any(|&x| x != 0.0));
        let Some(sign) = decide(p, *e) else {
            counts[kind][1] += 1;
            continue;
        };
        counts[kind][0] += 1;
        if kind == 0 {
            assert_eq!(sign, exact(p), "{p:?}");
            continue;
        }
        assert_ne!(sign, Sign::Zero, "{p:?} e = {e:?}");
        // Powers of two, far from the subnormals: halving them is exact.
        let half = e.map(|x| x / 2.0);
        assert_eq!(half.map(|x| x * 2.0), *e);
        // Every coordinate at its lowest or at its highest, but the one of
        // `flip`, at the other end.
        let corner = |high: bool, flip: Option<(usize, usize)>| -> [[Dyadic; 3]; 3] {
            std::array::from_fn(|i| {
                std::array::from_fn(|k| {
                    let (x, d) = (Dyadic::from_f64(p[i][k]), Dyadic::from_f64(half[k]));
                    if high != (flip == Some((i, k))) {
                        &x + &d
                    } else {
                        &x - &d
                    }
                })
            })
        };
        for high in [false, true] {
            let flips = (0..3).flat_map(|i| (0..3).map(move |k| Some((i, k))));
            for flip in std::iter::once(None).chain(flips) {
                assert_eq!(
                    exact_at(&corner(high, flip)),
                    sign,
                    "{p:?} e = {e:?}, corner {high} {flip:?}"
                );
            }
        }
    }
    // The cases come in pairs with the same `e`, the first at most the
    // bound and the second above it.
    for pair in cases.chunks(2) {
        let [(below, e), (above, _)] = pair else {
            panic!("the cases come in pairs");
        };
        if e.iter().all(|&x| x == 0.0) {
            continue;
        }
        let twice = e.map(|x| 2.0 * x);
        assert_eq!(decide(below, twice), None, "{below:?} e = {twice:?}");
        let half = e.map(|x| x / 2.0);
        assert_eq!(
            decide(above, half),
            Some(exact(above)),
            "{above:?} e = {half:?}"
        );
    }
    counts
}
